import ast, hashlib, json
from pathlib import Path
from radon.complexity import cc_visit
from tools.quality_gate_support import scan_complexity_entries, scan_oversize_entries
paths=["core/services/workbench/actual_gantt_chain.py","core/services/scheduler/gantt_critical_chain.py"]
all_functions={}
for name in paths:
    raw=Path(name).read_bytes()
    rows=[]
    def add(block):
        rows.append({"name":block.name,"line":block.lineno,"complexity":block.complexity})
        for child in getattr(block,"closures",()):
            add(child)
        for method in getattr(block,"methods",()):
            add(method)
    for block in cc_visit(raw.decode("utf-8")):
        add(block)
    all_functions[name]={"sha256":hashlib.sha256(raw).hexdigest(),"functions":rows}
result={"files":all_functions,"complexity_violations":scan_complexity_entries(paths),"size_violations":scan_oversize_entries(paths)}
print(json.dumps(result,ensure_ascii=False))
raise SystemExit(1 if result["complexity_violations"] or result["size_violations"] else 0)

